export function plainForStudents(text: string) {
  return makePlain(text);
}

export function studentTitleFor(experience: ProgramExperience) {
  return studentTitleOverrides[experience.id] ?? makePlain(experience.title);
}

export function studentStepsFor(experience: ProgramExperience): StudentStep[] {
  const actions = exactStudentSteps[experience.id] ?? experience.steps.map(makePlain);
  return actions.map((action, index) => ({
    title: stepTitles[index] ?? `Step ${index + 1}`,
    action,
    show: index === actions.length - 1
      ? `Show your finished work: ${makePlain(experience.product)}.`
      : "Point to what you noticed, chose, tested, or changed.",
  }));
}

