  fair_play: { term: "fair play", meaning: "safe, honest play that includes and respects others", example: "A fair rule gives everyone a useful way back into the game." },
  feedback: { term: "feedback", meaning: "specific information used to improve work", example: "The tester showed exactly where the directions became unclear." },
  game_mechanic: { term: "game mechanic", meaning: "an action or rule that shapes how a game works", example: "Collecting three keys is the mechanic that opens the final door." },
  genre: { term: "genre", meaning: "a category of text with shared features", example: "Mystery, fantasy, biography, and news report are genres." },
  goal: { term: "goal", meaning: "a result you plan to work toward", example: "A useful goal includes a first step and a check date." },
  imagery: { term: "imagery", meaning: "language that helps an audience picture, hear, or feel something", example: "The rain tapped the railing like quick fingers." },
  inference: { term: "inference", meaning: "an idea worked out from evidence and reasoning", example: "An empty wet umbrella suggests rain, but does not prove who used it." },
