  leadership: { term: "leadership", meaning: "actions that help a group move forward safely and fairly", example: "Making space for a quiet idea can be leadership." },
  limit: { term: "limit", meaning: "something evidence, a model, or a design cannot do or show", example: "A map shows routes but not every person's experience." },
  locomotor: { term: "locomotor movement", meaning: "movement that travels from one place to another", example: "Running, hopping, and rolling are locomotor movements." },
  manipulative: { term: "manipulative skill", meaning: "controlling an object with hands, feet, or equipment", example: "Throwing, catching, kicking, and striking are manipulative skills." },
  metaphor: { term: "metaphor", meaning: "a comparison that says one thing is another to create meaning", example: "Calling the heart a pump helps in some ways but has limits." },
  milestone: { term: "milestone", meaning: "an important checkpoint in a longer project", example: "Finish the test version before the feedback milestone." },
