  place_value: { term: "place value", meaning: "the value a digit has because of its position", example: "The 5 in 0.05 means five hundredths." },
  probability: { term: "probability", meaning: "how likely an outcome is", example: "A fair six-sided die has a 1 in 6 probability of rolling a 4." },
  prototype: { term: "test version", meaning: "an early version made so people can try it and help improve it", example: "Paper buttons can test an app idea before coding." },
  ratio: { term: "ratio", meaning: "a comparison between two quantities", example: "A 2:3 ratio means two parts of one amount for every three of another." },
  reliable: { term: "reliable source", meaning: "a source that is consistently careful, accurate, and open about its evidence", example: "Check the creator, date, purpose, evidence, and other sources." },
  revise: { term: "revise", meaning: "change ideas, structure, or design to make work stronger", example: "Revision is more than fixing spelling." },
  rhythm: { term: "rhythm", meaning: "a pattern of sounds, silences, or movements over time", example: "Clap-clap-pause can become a repeating rhythm." },
  router: { term: "router", meaning: "a device that directs information packets between networks", example: "A router chooses where a packet should travel next." },
  scale: { term: "scale", meaning: "the values or size relationship used in a graph, map, or model", example: "Changing a graph's scale can change its first impression." },
  sequence: { term: "sequence", meaning: "the order in which parts happen or appear", example: "Changing the sequence of clips can suggest a different cause." },
  setting: { term: "setting", meaning: "where and when a story happens", example: "The game begins in a flooded forest at dawn." },
  source: { term: "source", meaning: "where information, evidence, or a creative work comes from", example: "Record the creator, title, organization, and date when possible." },
  story_block: { term: "story block", meaning: "a short piece of story information placed where the player needs it", example: "A warning appears before the player chooses a tunnel." },
  strength: { term: "strength", meaning: "an ability or helpful action supported by evidence", example: "I organized the materials and helped the group restart." },
  strategy: { term: "strategy", meaning: "a planned way to reach a goal or solve a problem", example: "Moving into open space is a game strategy." },
  success_rules: { term: "success rules", meaning: "clear statements describing what a working design must do", example: "A new player can begin, follow the story, and reach the ending without hints." },
  symbol: { term: "symbol", meaning: "an image, sound, object, or action used to represent an idea", example: "A broken chain can symbolize freedom." },
  system: { term: "system", meaning: "connected parts that work together", example: "A network includes devices, routers, messages, and rules." },
  tableau: { term: "tableau", meaning: "a still image made with bodies or figures", example: "Hold one frozen pose to show the moment power changes." },
  theoretical: { term: "theoretical probability", meaning: "the probability predicted from all equally likely outcomes", example: "There are two even numbers on a four-part equal spinner, so the probability is 2/4." },
  trend: { term: "trend", meaning: "a general direction or pattern in data", example: "The values generally rise, even though one point drops." },
  turning_point: { term: "turning point", meaning: "a moment when the problem, plan, or understanding changes", example: "The map is wrong, and the player must follow the river instead." },
  variable: { term: "variable", meaning: "a symbol for a number that can change or is not yet known", example: "In 3n + 1, n is the variable." },
  well_being: { term: "well-being", meaning: "physical, emotional, mental, and social health together", example: "Sleep, belonging, movement, safety, and support can affect well-being." },
