export function mediaFor(experienceId: string): ExperienceMedia[] {
  if (experienceId === "edit-room") return [...experienceMedia[experienceId], ...experienceMedia["edit-room-source"]];
  return experienceMedia[experienceId] ?? [];
}

export function spacesBookendsFor(arc: ProgramArc, experiences: ProgramExperience[]) {
  if (arc.id === "adst-game") return {
    entry: {
      title: "Optional entry snapshot",
      prompt: "What makes a game easy to understand and a story worth following? Keep this local or add it to the beginning of the same Bloxels post.",
      choices: ["Annotated image or sketch", "20–30 second audio", "Quick game/story T-chart"],
    },
    exit: {
      title: "Required combined project evidence",
      prompt: "Use one Bloxels post: show the game, one story change, one game or access change, the playtest evidence, and your individual contribution.",
      choices: ["Teacher-recorded class showcase clip", "Teacher-added game link", "Photo of the equivalent paper game", "Audio, written, or video reflection"],
    },
  };
  const finalExperience = experiences.findLast(item => arc.experienceIds.includes(item.id) && (spacesPolicyForActivity(item.id)?.decision ?? item.spacesUse) !== "none")
    ?? experiences.findLast(item => arc.experienceIds.includes(item.id));
  const finalPolicy = finalExperience ? spacesPolicyForActivity(finalExperience.id) : null;
  const exitPrompt = finalExperience
    ? finalPolicy?.decision === "required"
      ? `${finalPolicy.teacherPrompt} Explain what changed in your thinking and point to the evidence.`
      : finalPolicy?.decision === "reuse"
        ? `${finalPolicy.teacherPrompt} Choose the part of “${finalExperience.title}” that best supports that shared artifact.`
        : `Choose useful evidence from “${finalExperience.title}.” Explain what changed in your thinking and point to the evidence.`
    : "Choose one piece that shows how your thinking changed.";
  return {
    entry: {
      title: "Optional entry snapshot",
      prompt: `Before this arc, respond to: ${arc.question}`,
      choices: ["20–30 second audio", "One image or first model with a caption", "Two or three sentences", "A quick diagram plus one wonder"],
    },
    exit: {
      title: "Possible end-of-arc evidence",
      prompt: exitPrompt,
      choices: ["Photo of a model or creation", "Short video demonstration", "Audio explanation", "Written or visual reflection"],
    },
  };
}
